function() {
  // 1. Tenta pegar o selo. Se não existir, o GTM já retorna undefined automaticamente
  var adSealValue = {{[VAR] dataLayer - adInfo.ad.seal}};

  if (adSealValue !== undefined && adSealValue !== null && adSealValue !== '') {
    return adSealValue;
  }

  // 2. Lógica de contingência baseada na página e URL
  var pageHrefLower = window.location.href.toLowerCase();
  var pageName = {{[VAR] dataLayer - pageInfo.pageName}} || "";
  var sitePath = {{[VAR] dataLayer - siteInfo.pathname}} || "";

  // Verificação 1: Festival da Mudança
  if (pageName.includes('/resultado-pesquisa') && (pageHrefLower.includes('festival_da_mudanca') || pageHrefLower.includes('festival-da-mudanca'))) {
    return 'FESTIVAL_DA_MUDANCA';
  } 

  // Verificação 2: Festival Minha Casa Própria/Vida
  // Ajustado para aceitar o pageName do seu dataLayer e o termo "propria" da URL
  else if (
    (pageName.includes('/feirao') || sitePath.includes('/feirao/')) && 
    (pageHrefLower.includes('minha-casa-propria') || pageHrefLower.includes('minha-casa-nova'))
  ) {
    return 'festival_minha_casa_minha_vida';
  } 

  return undefined;
}

