function() {
  var cUserId = {{[VAR] Cookie - userID}};
  var dtUserId = {{[VAR] dataLayer - userInfo.user_id}};
  var dtUser_id = {{[VAR] dataLayer - user_id}};
  var dtLoginUserId = {{[VAR] dataLayer - login.user_id}};
  var invalidValuesRegex = /^(|unidentified|undefined|null|not set|no id|guest)$/i;

  function isValidUserId(value) {
    return !(value === null || 
             value === undefined || 
             String(value).trim() === '' || 
             invalidValuesRegex.test(String(value).trim()));
  }

  if (isValidUserId(cUserId)) {
    return cUserId;
  } 
  else if (isValidUserId(dtUserId)) {
    return dtUserId;
  }
  else if (isValidUserId(dtUser_id)) {
    return dtUser_id;
  }
  else if (isValidUserId(dtLoginUserId)) {
    return dtLoginUserId;
  }
  else {
    return undefined;
  }
}

function() {
  try {
    var categories = [];
    var categoryText = '';
    Insider.utils.getDataFromIO('product', 'taxonomy', []).map(function(category) {
      categoryText = (category || '').toString().trim();
      categoryText !== '' && categories.indexOf(categoryText) === -1 && categories.push(categoryText);
    });
    if (categories.length === 0) {
      Insider.dom('.listing-breadcrumb li[class*=breadcrumb]:visible a, .listing-breadcrumb li[class*=bread' + 'crumb]:visible p ').accessNodes(function(category) {
        categoryText = Insider.dom(category).text().trim();
        categoryText !== '' && categories.indexOf(categoryText) === -1 && categories.push(categoryText);
      });
    }
    return categories;
  } catch (e) {
    return undefined;
  }
}

