function() {
  return function(getMinimum) {

  // 1. Encontrar todos os números na string usando expressão regular
  var numerosEncontrados = getMinimum.match(/\d+/g);

  // 2. Verificar se algum número foi encontrado
  if (!numerosEncontrados) {
    return undefined; // Retorna 0 ou outro valor padrão se nenhum número for encontrado
  }

  // 3. Converter o array de strings em um array de números inteiros
  var arrayDeNumeros = numerosEncontrados.map(Number);

  // 4. Encontrar o menor número no array
  // Aplica Math.min() para o array usando Function.prototype.apply para compatibilidade
  var maiorNumero = Math.min.apply(null, arrayDeNumeros);

  return maiorNumero;
};
}

function() {
  return function(paramName) {
    try {
      // Obtém a URL atual
      var url = window.location.href;

      // Cria um objeto URL para facilitar a extração
      var urlObj = new URL(url);

      // Extrai o valor do parâmetro
      var paramValue = urlObj.searchParams.get(paramName);

      // Retorna o valor decodificado (converte %20 para espaço, etc)
      return paramValue ? decodeURIComponent(paramValue) : undefined;

    } catch(e) {
      // Em caso de erro, retorna undefined
      return undefined;
    }
  };
}

