function() {
  var filters = {{[VAR] DataLayer - ranking.filter}};

  if (!filters) return "";

  var result = [];

  // Percorre cada chave do objeto
  for (var key in filters) {
    var value = filters[key];

    if (Array.isArray(value)) {
      // Se for um array, verificamos se os itens são objetos ou valores simples
      value.forEach(function(item) {
        if (typeof item === 'object' && item !== null) {
          // Extrai os valores de dentro de objetos (ex: addresses)
          for (var subKey in item) {
            if (item[subKey]) result.push(item[subKey]);
          }
        } else {
          // Se for valor simples no array (ex: bedrooms)
          result.push(item);
        }
      });
    } else if (typeof value === 'string' || typeof value === 'number') {
      // Se for um valor simples direto na chave (ex: business_type)
      result.push(value);
    }
  }

  // Remove duplicatas e valores vazios, depois une com vírgula
  return result.filter(function(item, pos) {
    return item && result.indexOf(item) == pos;
  }).join(', ');
}

