function() {
  var originalStepName = {{[VAR] simulator.step_name}};
  var clickText = {{Click Text}};

  if (clickText) {
    clickText = clickText.toLowerCase().trim();

    if (clickText === 'explorar imóveis' || clickText === 'explorar imoveis') {
      return 'simulation_result_explore_properties';
    }

    if (clickText === 'nova simulação' || clickText === 'nova simulacao') {
      return 'simulation_result_new_simulation';
    }
  }

  return originalStepName;
}

function() {
  var stepName = {{[VAR] simulator.step_name}};
  var clickText = {{Click Text}};

  if (clickText) {
    clickText = clickText.toLowerCase().trim();

    if (clickText === 'explorar imóveis' || clickText === 'explorar imoveis') {
      return 'form_subsidy_simulator_explore_properties';
    }

    if (clickText === 'nova simulação' || clickText === 'nova simulacao') {
      return 'form_subsidy_simulator_new_simulation';
    }
  }

  switch (stepName) {
    case 'start':
      return 'form_subsidy_simulator_start';

    case 'family_income':
      return 'form_subsidy_simulator_family_income';

    case 'financial_profile':
      return 'form_subsidy_simulator_financial_profile';

    case 'personal_info':
      return 'form_subsidy_simulator_personal_info';

    case 'simulation_result':
      return 'form_subsidy_simulator_simulation_result';

    default:
      return 'form_subsidy_simulator';
  }
}

